import{f as t,o as a,c as d,a2 as o}from"./chunks/framework.BUDOXiIz.js";const m=JSON.parse('{"title":"29 — Casos de prueba de aceptación y criterios de aceptación por ola","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/29-criterios-y-casos-aceptacion-por-ola.md","filePath":"entregables-analisis-diseno/29-criterios-y-casos-aceptacion-por-ola.md","lastUpdated":null}'),r={name:"entregables-analisis-diseno/29-criterios-y-casos-aceptacion-por-ola.md"};function i(s,e,c,n,l,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="_29-—-casos-de-prueba-de-aceptacion-y-criterios-de-aceptacion-por-ola" tabindex="-1">29 — Casos de prueba de aceptación y criterios de aceptación por ola <a class="header-anchor" href="#_29-—-casos-de-prueba-de-aceptacion-y-criterios-de-aceptacion-por-ola" aria-label="Permalink to &quot;29 — Casos de prueba de aceptación y criterios de aceptación por ola&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Documento</td><td>29 — Casos de prueba de aceptación y criterios de aceptación por ola (portada)</td></tr><tr><td>Artefactos</td><td>9.2 Casos de prueba de aceptación; 9.3 Criterios de aceptación por ola (índice <code>00-INDICE.md</code>)</td></tr><tr><td>Producto</td><td>GoodApps Cooperativas</td></tr><tr><td>Versión</td><td>1.0</td></tr><tr><td>Fecha</td><td>05-11-2026</td></tr><tr><td>Estado</td><td>Borrador para revisión del equipo de producto, QA y del referente de la cooperativa piloto</td></tr><tr><td>Fuentes</td><td>Criterios de aceptación de los RF y escenarios ESC- de los anexos de <code>docs/especificacion/anexos/</code> (M01 a M19, T01 a T12); <code>docs/especificacion/03-plan-de-olas-y-prompts.md</code> (172 prompts, entregables y criterios de salida por ola); T07 §17 (corrida en paralelo); T08 (RNF medibles); <code>07-estrategia-pruebas.md</code> (niveles, ambientes, nomenclatura, severidades, casos AC-01 a AC-20); <code>08-plan-puesta-en-marcha.md</code> (checklist GO-xx); decisiones DEC-005, DEC-088 y DEC-089</td></tr></tbody></table><h2 id="control-de-versiones" tabindex="-1">Control de versiones <a class="header-anchor" href="#control-de-versiones" aria-label="Permalink to &quot;Control de versiones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Versión</th><th>Fecha</th><th>Cambio</th></tr></thead><tbody><tr><td>1.0</td><td>05-11-2026</td><td>Primera versión: formato del caso, criterios por ola O0 a O11, 196 casos CPA, suite de paralelo de LAG, matriz de cobertura y observaciones.</td></tr></tbody></table><h2 id="archivos-que-forman-el-documento" tabindex="-1">Archivos que forman el documento <a class="header-anchor" href="#archivos-que-forman-el-documento" aria-label="Permalink to &quot;Archivos que forman el documento&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th></tr></thead><tbody><tr><td><code>29-criterios-y-casos-aceptacion-por-ola.md</code> (esta portada)</td><td>Secciones 0 (propósito y relación con <code>07</code>), 1 (formato del caso), 2.0 (criterios comunes y resumen por ola), 4 (resumen de cobertura) y 5 (observaciones e inconsistencias)</td></tr><tr><td><a href="./29a-casos-aceptacion-o0-o3"><code>29a-casos-aceptacion-o0-o3.md</code></a></td><td>Secciones 2.1 a 2.4: criterios y casos de O0, O1, O2 y O3</td></tr><tr><td><a href="./29b-casos-aceptacion-o4-o7"><code>29b-casos-aceptacion-o4-o7.md</code></a></td><td>Secciones 2.5 a 2.8: criterios y casos de O4, O5, O6 y O7</td></tr><tr><td><a href="./29c-casos-aceptacion-o8-o11-paralelo"><code>29c-casos-aceptacion-o8-o11-paralelo.md</code></a></td><td>Secciones 2.9 a 2.12 (O8 a O11) y sección 3 (suite de paralelo ProCoop frente a GoodApps para LAG)</td></tr><tr><td><a href="./29d-matriz-cobertura"><code>29d-matriz-cobertura.md</code></a></td><td>Sección 4 detallada: universo por ola, escenarios no cubiertos y matriz caso → RF/ESC</td></tr></tbody></table><hr><h2 id="_0-proposito-alcance-y-relacion-con-la-estrategia-de-pruebas" tabindex="-1">0. Propósito, alcance y relación con la estrategia de pruebas <a class="header-anchor" href="#_0-proposito-alcance-y-relacion-con-la-estrategia-de-pruebas" aria-label="Permalink to &quot;0. Propósito, alcance y relación con la estrategia de pruebas&quot;">​</a></h2><p>Este documento traduce los criterios de aceptación de la especificación en casos de prueba de aceptación ejecutables y fija, para cada ola del plan, qué tiene que estar demostrado para darla por terminada. No agrega requisitos: cada caso cita el RF, el escenario (ESC-, TST-, CA-, AC-PER-, PR-POR-, NEG-, TEN-, RET-, T-TES-) o el criterio de salida del plan del que sale. Cuando una fuente no alcanza para definir un resultado esperado, el caso queda sin escribir y la falta va a la sección 5.</p><p>Relación con <code>07-estrategia-pruebas.md</code>:</p><table tabindex="0"><thead><tr><th>Tema</th><th>Regla en este documento</th></tr></thead><tbody><tr><td>Niveles</td><td>Se usan los niveles de <code>07</code>: unitarias, integración, contrato, extremo a extremo (Playwright con etiquetas <code>@Ox</code> y <code>@piloto-internet</code>), aceptación de usuario y regresión, más las suites transversales de aislamiento (<code>npm run test:isolation</code>), permisos negativos, idempotencia, propiedades y carga (k6). Cada caso indica su nivel.</td></tr><tr><td>Ambientes</td><td><code>local</code>, <code>ci</code>, <code>dev</code>, <code>staging</code>, <code>sandbox</code>, <code>demo</code>, <code>prod</code> y el ambiente aislado de migración, con el uso que les da <code>07</code>. La aceptación de usuario se hace en <code>sandbox</code> o en el tenant gemelo (RF-PLA-111); la carga se mide en <code>staging</code>; los ensayos de migración van al ambiente aislado.</td></tr><tr><td>Datos</td><td>Solo datos ficticios del juego canónico: TEN-001 &quot;Cooperativa Ejemplo A&quot; (<code>coop-ejemplo-a</code>, CUIT 30-99999991-0), TEN-002 &quot;Cooperativa Ejemplo B&quot;, socia Ana Demo (DNI 00000001), planes INT-100 e INT-300, equipos ONT-DEMO-0001 a ONT-DEMO-0010, hermanos A y B en DIR-CASA-001, lotes LE-01 y LE-02, corrida MIG-DEMO-001, correos <code>@example.com</code> y <code>@ejemplo.test</code>. Ningún caso usa datos reales, secretos ni código de ProCoop.</td></tr><tr><td>Severidades</td><td>S1 a S4 de <code>07</code> §12.1. Un defecto S1 o S2 abierto en un caso impide aprobarlo.</td></tr><tr><td>Casos AC de <code>07</code></td><td>Los casos AC-01 a AC-20 de <code>07</code> §15 se ejecutan dentro de los casos CPA que los citan en su campo &quot;Cubre&quot; (por ejemplo, AC-20 dentro de CPA-O7-101 a CPA-O7-114). <code>07</code> sigue siendo la fuente del protocolo de aceptación de usuario; acá está el detalle paso a paso.</td></tr><tr><td>Precedencia</td><td>Si un resultado esperado de un caso difiere del texto del ID citado, vale el ID citado y la diferencia se registra como defecto del caso, no del sistema.</td></tr></tbody></table><h2 id="_1-formato-del-caso-de-prueba-de-aceptacion" tabindex="-1">1. Formato del caso de prueba de aceptación <a class="header-anchor" href="#_1-formato-del-caso-de-prueba-de-aceptacion" aria-label="Permalink to &quot;1. Formato del caso de prueba de aceptación&quot;">​</a></h2><h3 id="_1-1-campos-obligatorios" tabindex="-1">1.1 Campos obligatorios <a class="header-anchor" href="#_1-1-campos-obligatorios" aria-label="Permalink to &quot;1.1 Campos obligatorios&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Campo</th><th>Contenido</th></tr></thead><tbody><tr><td>ID</td><td><code>CPA-&amp;lt;ola&gt;-NNN</code>, con <code>&amp;lt;ola&gt;</code> de O0 a O11 y NNN correlativo dentro de la ola. Los casos de la suite de paralelo de LAG usan el bloque CPA-O7-101 a CPA-O7-114.</td></tr><tr><td>Título</td><td>Qué demuestra el caso, en una línea.</td></tr><tr><td>Cubre</td><td>RF, escenarios y criterios de salida (CS-Ox-NN) que el caso demuestra. Es la fuente de la matriz de la sección 4.</td></tr><tr><td>Precondiciones</td><td>Estado previo del sistema, casos que deben haber corrido antes, parámetros y flags.</td></tr><tr><td>Datos ficticios</td><td>Datos concretos del juego canónico o derivados de él.</td></tr><tr><td>Pasos y resultado esperado</td><td>Escenario Gherkin (Dado / Cuando / Entonces / Y) en O0 a O7 y en la suite de paralelo; en O8 a O11, tabla con columnas &quot;Cuando&quot; y &quot;Entonces&quot;.</td></tr><tr><td>Prioridad · Tipo</td><td>Ver 1.2 y 1.3.</td></tr><tr><td>Nivel · Ambiente</td><td>Nivel de <code>07</code> y ambiente donde se ejecuta. En las tablas de O8 a O11 se aplica el nivel extremo a extremo en <code>staging</code>, salvo que el caso diga otra cosa.</td></tr></tbody></table><h3 id="_1-2-prioridad" tabindex="-1">1.2 Prioridad <a class="header-anchor" href="#_1-2-prioridad" aria-label="Permalink to &quot;1.2 Prioridad&quot;">​</a></h3><p>La escala es una convención de este documento para ordenar la ejecución; no es un requisito de la especificación (OBS-25-16).</p><table tabindex="0"><thead><tr><th>Prioridad</th><th>Significado</th><th>Efecto en la salida de la ola</th></tr></thead><tbody><tr><td>P1</td><td>Camino crítico del piloto, aislamiento entre tenants, dinero, fiscal, seguridad o un criterio de salida del plan</td><td>Debe aprobarse al 100 %. Bloquea la salida de la ola y, en O7 y la suite de paralelo, la decisión de seguir o no seguir del corte de LAG.</td></tr><tr><td>P2</td><td>Funcionalidad principal de la ola fuera del camino crítico</td><td>Debe aprobarse al 100 % o tener un defecto S3 o S4 con ticket, responsable y ola de corrección.</td></tr><tr><td>P3</td><td>Variantes y casos secundarios</td><td>Puede quedar pendiente con ticket; no bloquea la salida.</td></tr></tbody></table><h3 id="_1-3-tipos" tabindex="-1">1.3 Tipos <a class="header-anchor" href="#_1-3-tipos" aria-label="Permalink to &quot;1.3 Tipos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo</th><th>Cuándo se usa</th></tr></thead><tbody><tr><td>Funcional</td><td>Comportamiento de negocio descrito por un RF o escenario.</td></tr><tr><td>Regresión</td><td>Caso que se vuelve a ejecutar en olas siguientes para demostrar que lo ya aprobado sigue funcionando (por ejemplo, el recorrido del piloto Internet en cada ola posterior a O6).</td></tr><tr><td>Paralelo</td><td>Comparación de resultados entre ProCoop y GoodApps durante la corrida en paralelo (sección 3).</td></tr><tr><td>No funcional</td><td>Rendimiento, carga, disponibilidad, accesibilidad, seguridad u observabilidad medidos contra un RNF de T08.</td></tr></tbody></table><h3 id="_1-4-plantilla" tabindex="-1">1.4 Plantilla <a class="header-anchor" href="#_1-4-plantilla" aria-label="Permalink to &quot;1.4 Plantilla&quot;">​</a></h3><div class="language-gherkin vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">gherkin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Escenario</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CPA-Ox-NNN &lt;título&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  Dado </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;precondición con datos ficticios&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  Cuando </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;acción del usuario o del sistema&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  Entonces </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;resultado esperado verificable&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  Y </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;resultado adicional, incluida auditoría o evento cuando el ID citado lo exige&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_1-5-ejecucion-y-evidencia" tabindex="-1">1.5 Ejecución y evidencia <a class="header-anchor" href="#_1-5-ejecucion-y-evidencia" aria-label="Permalink to &quot;1.5 Ejecución y evidencia&quot;">​</a></h3><ul><li>La prueba automatizada que implementa un caso lleva su ID en el nombre (con la forma <code>CPA-Ox-NNN &amp;lt;título&gt;</code>), para que <code>npm run trace:check</code> relacione caso, RF y prueba.</li><li>La evidencia de cada ejecución (reporte, capturas sin datos personales, informes k6, actas) se guarda en <code>docs/evidencias/&amp;lt;ola&gt;/</code>.</li><li>Un caso se aprueba cuando todos los &quot;Entonces&quot; se cumplen en el ambiente indicado y no hay defectos S1 o S2 abiertos asociados.</li><li>Los casos de tipo regresión se incluyen en la suite de regresión de <code>07</code> al aprobarse por primera vez.</li></ul><h2 id="_2-0-criterios-comunes-de-aceptacion-y-resumen-por-ola" tabindex="-1">2.0 Criterios comunes de aceptación y resumen por ola <a class="header-anchor" href="#_2-0-criterios-comunes-de-aceptacion-y-resumen-por-ola" aria-label="Permalink to &quot;2.0 Criterios comunes de aceptación y resumen por ola&quot;">​</a></h2><h3 id="_2-0-1-entrada-a-la-ejecucion-de-aceptacion-de-una-ola" tabindex="-1">2.0.1 Entrada a la ejecución de aceptación de una ola <a class="header-anchor" href="#_2-0-1-entrada-a-la-ejecucion-de-aceptacion-de-una-ola" aria-label="Permalink to &quot;2.0.1 Entrada a la ejecución de aceptación de una ola&quot;">​</a></h3><p>Se aplican los cinco criterios de entrada de <code>07</code> §11.1. Además, los casos de la ola deben estar revisados contra los ID que citan y los datos ficticios cargados con <code>npm run seed:demo</code>.</p><h3 id="_2-0-2-salida-comun-de-todas-las-olas" tabindex="-1">2.0.2 Salida común de todas las olas <a class="header-anchor" href="#_2-0-2-salida-comun-de-todas-las-olas" aria-label="Permalink to &quot;2.0.2 Salida común de todas las olas&quot;">​</a></h3><p>Una ola se da por terminada cuando se cumplen a la vez:</p><ol><li>Los criterios de salida comunes de <code>07</code> §11.2 y los específicos de <code>07</code> §11.3 para esa ola.</li><li>Las condiciones CS-Ox-NN de la ola (secciones 2.1 a 2.12), que transcriben los criterios de salida del plan <code>03</code> para esa ola.</li><li>Los RF de la ola en estado <code>Implementado</code> o <code>Parcial</code> con la parte de esa ola cumplida, y <code>npm run trace:check</code> sin faltantes (<code>03</code> R20; PRO-GEN-02).</li><li>Los casos CPA de prioridad P1 aprobados al 100 % y los P2 según 1.2.</li><li>La prueba de carga obligatoria aprobada en O0, O4, O5, O6, O7 y O11 (RNF-NFR-145) y, de O4 a O7 y en O11, la capacidad de tenant grande (RNF-NFR-024).</li><li>La regresión de las olas anteriores en verde, incluido el recorrido del piloto Internet a partir de O6.</li></ol><h3 id="_2-0-3-definicion-de-terminado-de-un-prompt-y-de-una-ola" tabindex="-1">2.0.3 Definición de terminado de un prompt y de una ola <a class="header-anchor" href="#_2-0-3-definicion-de-terminado-de-un-prompt-y-de-una-ola" aria-label="Permalink to &quot;2.0.3 Definición de terminado de un prompt y de una ola&quot;">​</a></h3><p>Se adopta la definición de terminado de <code>07</code> §11.4 (nueve puntos) y la regla R16 del plan. Un prompt no se cierra si sus pruebas no corren en el CI; una ola no se cierra si su prompt de integración (columna &quot;Prompt de integración&quot; de la tabla siguiente) no está aprobado.</p><h3 id="_2-0-4-resumen-por-ola" tabindex="-1">2.0.4 Resumen por ola <a class="header-anchor" href="#_2-0-4-resumen-por-ola" aria-label="Permalink to &quot;2.0.4 Resumen por ola&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ola</th><th>Hito</th><th>RF</th><th>Prompts</th><th>Prompt de integración</th><th>Carga obligatoria</th><th>Casos CPA</th><th>Archivo</th></tr></thead><tbody><tr><td>O0</td><td>Fundaciones</td><td>305</td><td>21</td><td>PRO-O0-21</td><td>Sí: login y lectura por ID</td><td>15</td><td><code>29a</code></td></tr><tr><td>O1</td><td>Plataforma, IAM, configuración y workflow</td><td>458</td><td>20</td><td>PRO-O1-20</td><td>No</td><td>18</td><td><code>29a</code></td></tr><tr><td>O2</td><td>Personas, catálogo, landing, portal base, CRM y comunidad</td><td>614</td><td>19</td><td>PRO-O2-19</td><td>No</td><td>19</td><td><code>29a</code></td></tr><tr><td>O3</td><td>Técnica del piloto Internet</td><td>319</td><td>13</td><td>PRO-O3-13</td><td>No</td><td>16</td><td><code>29a</code></td></tr><tr><td>O4</td><td>Tarifas, facturación, ARCA e impuestos básicos</td><td>424</td><td>16</td><td>PRO-O4-16</td><td>Sí: lote de 20.000</td><td>19</td><td><code>29b</code></td></tr><tr><td>O5</td><td>Cuenta corriente, cobranza, pasarelas, tesorería y núcleo contable</td><td>469</td><td>14</td><td>PRO-O5-14</td><td>Sí: webhooks 500/min</td><td>18</td><td><code>29b</code></td></tr><tr><td>O6</td><td>Mora, corte, reconexión y convenios: cierre del piloto Internet</td><td>244</td><td>11</td><td>PRO-O6-11</td><td>Sí: mora de 20.000</td><td>17</td><td><code>29b</code></td></tr><tr><td>O7</td><td>Servicios medidos, migración comercial vigente, paralelo y corte comercial de LAG (DEC-089)</td><td>298 (antes 274, DEC-089)</td><td>12 (antes 10)</td><td>PRO-O7-10</td><td>Sí: 50.000 lecturas</td><td>21</td><td><code>29b</code></td></tr><tr><td>O7 (paralelo LAG)</td><td>Suite de paralelo ProCoop frente a GoodApps</td><td>—</td><td>—</td><td>—</td><td>—</td><td>14</td><td><code>29c</code></td></tr><tr><td>O8</td><td>ERP administrativo y contabilidad completa</td><td>462</td><td>15</td><td>PRO-O8-15</td><td>No</td><td>11</td><td><code>29c</code></td></tr><tr><td>O9</td><td>Personal y sueldos</td><td>163</td><td>9</td><td>PRO-O9-09</td><td>No</td><td>7</td><td><code>29c</code></td></tr><tr><td>O10</td><td>Institucional, servicios sociales, flota, telefonía, TV, fabricación y turnero</td><td>383</td><td>14</td><td>PRO-O10-14</td><td>No</td><td>10</td><td><code>29c</code></td></tr><tr><td>O11</td><td>BI, APIs de terceros, migración repetible y corte administrativo (DEC-089; antes &quot;paralelo y corte&quot;)</td><td>65 (antes 90, y 89 tras la corrección del plan; DEC-089)</td><td>8 (antes 10)</td><td>PRO-O11-10</td><td>Sí: carga completa</td><td>11</td><td><code>29c</code></td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>4.204</strong> (antes 4.203)</td><td><strong>172</strong></td><td></td><td></td><td><strong>196</strong></td><td></td></tr></tbody></table><p>O0 a O7 forman el camino crítico del piloto (Internet como primer servicio según DEC-005, y servicios medidos de LAG según DEC-088 y DEC-089), por eso sus casos están en Gherkin y con más detalle. O8 a O11 tienen los casos clave en tabla.</p><h2 id="suite-de-paralelo-de-lag-ubicacion-de-la-seccion-3" tabindex="-1">Suite de paralelo de LAG (ubicación de la sección 3) <a class="header-anchor" href="#suite-de-paralelo-de-lag-ubicacion-de-la-seccion-3" aria-label="Permalink to &quot;Suite de paralelo de LAG (ubicación de la sección 3)&quot;">​</a></h2><p>La sección 3 está en <a href="./29c-casos-aceptacion-o8-o11-paralelo"><code>29c-casos-aceptacion-o8-o11-paralelo.md</code></a>. Define el alcance, el momento (después de O7, etapa E1), el criterio de aprobación por servicio de T07 §17.4 y los 14 casos CPA-O7-101 a CPA-O7-114 para electricidad, gas y prepago. Su aprobación es la evidencia de las condiciones GO-02 y GO-26 del checklist de <code>08</code> para el corte comercial.</p><h2 id="_4-resumen-de-la-matriz-de-cobertura" tabindex="-1">4. Resumen de la matriz de cobertura <a class="header-anchor" href="#_4-resumen-de-la-matriz-de-cobertura" aria-label="Permalink to &quot;4. Resumen de la matriz de cobertura&quot;">​</a></h2><p>Definición: el universo de cada ola son los escenarios con ID de referencia (ESC-, TST-, CA-, AC-PER-, PR-POR-, NEG-, TEN-, RET-, T-TES-, A1 a A16 y criterios numerados de M02, M05 y M06) asignados a esa ola; un escenario está cubierto si al menos un caso CPA lo cita en &quot;Cubre&quot;. Los RF se cubren a través de esos escenarios y de <code>npm run trace:check</code>; las condiciones CS-Ox-NN de cada ola están cubiertas al 100 % en todas las olas. El detalle (universo, faltantes y matriz caso por caso) está en <a href="./29d-matriz-cobertura"><code>29d-matriz-cobertura.md</code></a>.</p><table tabindex="0"><thead><tr><th>Ola</th><th>Casos</th><th>Escenarios del universo</th><th>Cubiertos</th><th>Cobertura</th></tr></thead><tbody><tr><td>O0</td><td>15</td><td>60</td><td>60</td><td>100,0 %</td></tr><tr><td>O1</td><td>18</td><td>125</td><td>100</td><td>80,0 %</td></tr><tr><td>O2</td><td>19</td><td>136</td><td>109</td><td>80,1 %</td></tr><tr><td>O3</td><td>16</td><td>70</td><td>67</td><td>95,7 %</td></tr><tr><td>O4</td><td>19</td><td>85</td><td>83</td><td>97,6 %</td></tr><tr><td>O5</td><td>18</td><td>125</td><td>117</td><td>93,6 %</td></tr><tr><td>O6</td><td>17</td><td>78</td><td>77</td><td>98,7 %</td></tr><tr><td>O7</td><td>21</td><td>110</td><td>106</td><td>96,4 %</td></tr><tr><td>Paralelo LAG</td><td>14</td><td>22</td><td>22</td><td>100,0 %</td></tr><tr><td>O8</td><td>11</td><td>76</td><td>61</td><td>80,3 %</td></tr><tr><td>O9</td><td>7</td><td>30</td><td>29</td><td>96,7 %</td></tr><tr><td>O10</td><td>10</td><td>121</td><td>95</td><td>78,5 %</td></tr><tr><td>O11</td><td>11</td><td>59</td><td>51</td><td>86,4 %</td></tr><tr><td><strong>Total</strong></td><td><strong>196</strong></td><td><strong>1.097</strong></td><td><strong>977</strong></td><td><strong>89,1 %</strong></td></tr></tbody></table><p>Para el camino crítico (O0 a O7 y paralelo) la cobertura es 741 de 811 escenarios (91,4 %); lo no cubierto de O1 y O2 son variantes de configuración, comunidad y portal que no están en el recorrido del piloto y quedan como deuda de casos para la versión 1.1.</p><h2 id="_5-observaciones-e-inconsistencias-detectadas" tabindex="-1">5. Observaciones e inconsistencias detectadas <a class="header-anchor" href="#_5-observaciones-e-inconsistencias-detectadas" aria-label="Permalink to &quot;5. Observaciones e inconsistencias detectadas&quot;">​</a></h2><p>Lo que sigue se registra sin corregir la especificación. Cada observación indica cómo la tratan los casos de este documento.</p><table tabindex="0"><thead><tr><th>ID</th><th>Observación</th><th>Fuentes involucradas</th><th>Tratamiento en este documento</th></tr></thead><tbody><tr><td>OBS-25-01</td><td>Los RF de corrida en paralelo y corte (RF-MIG-070 a RF-MIG-076 y RF-MIG-080 a RF-MIG-089) están asignados a O11 en T07 (incluida la columna &quot;Por ola&quot; de §9.1) y en el plan, pero DEC-089 exige el paralelo de electricidad, gas y prepago y el corte comercial de LAG después de O7. Ningún prompt de O7 adelanta esas capacidades.</td><td>DEC-089; T07 §9.1; <code>03</code> O11</td><td>La suite de paralelo se identifica como CPA-O7-101 a CPA-O7-114 y se ejecuta al cerrar O7; su ejecución depende de que esas capacidades estén disponibles antes de O11. <strong>Resuelta (05-11-2026):</strong> el plan <code>03</code> §21.7 pasa esos RF, RF-MIG-006 y la migración de datos vigentes comerciales a O7 (PRO-O7-11 y PRO-O7-12).</td></tr><tr><td>OBS-25-02</td><td>El criterio de salida de O11 (<code>03</code> §15.2) habla de &quot;un ciclo&quot; de paralelo y de una copia de ejemplo, mientras PRM-MIG-041 y PA-MIG-02 fijan 2 ciclos consecutivos aprobados por servicio.</td><td><code>03</code> §15.2; T07 PRM-MIG-041</td><td>CS-O11-02 y la suite de paralelo exigen 2 ciclos por servicio. <strong>Resuelta (05-11-2026):</strong> <code>03</code> §11.2 y §15.2 exigen los ciclos de PRM-MIG-041 (default 2).</td></tr><tr><td>OBS-25-03</td><td>El plan y <code>07</code> citan la sección de escenarios de Internet de T12 parte 1 como §1.6, cuando está en §1.7, y ubican los escenarios de energía, agua, telefonía y TV en T12 parte 2 (<code>03</code> §11.8, PRO-O7-10, PRO-O10-14, <code>07</code> §11.3), cuando están en T12 parte 1 §2.7 a §8.7.</td><td><code>03</code>; <code>07</code>; T12</td><td>Los casos citan los ID ESC-SRV-xx con su ubicación real. <strong>Resuelta (05-11-2026):</strong> el plan cita T12 parte 1 §1.7 y las fichas de energía, agua, cloacas, gas, telefonía y TV en parte 1; <code>07</code> corregido igual.</td></tr><tr><td>OBS-25-04</td><td>ESC-SRV-INT-01 usa importes 25.000, 30.000 y 60.000, distintos de ESC-TAR-03, M02 §18 y M04 9.3.9 (primer comprobante de INT-100 de 30.000,00). Coincide con OBS-01 de <code>07</code>.</td><td>T12 §1.7; M02 §18; M04</td><td>Los casos usan los valores del juego canónico de M02 §18 (5.000 − 2.500 + 15.000 − 7.500 + 20.000 = 30.000,00). <strong>Resuelta:</strong> ESC-SRV-INT-01 ya usa el seed único de M02 §18.</td></tr><tr><td>OBS-25-05</td><td>ESC-SRV-GAS-02 y ESC-SRV-GAS-07 describen consumo bloqueado, esquema que DEC-085, RN-TAR-035 y ESC-MED-17 reemplazaron.</td><td>T12 §7.7; DEC-085; M04; M03</td><td>Los casos de gas siguen DEC-085 y ESC-MED-17. <strong>Resuelta (05-11-2026):</strong> ESC-SRV-GAS-02 y 07 siguen RN-TAR-035 (DEC-085).</td></tr><tr><td>OBS-25-06</td><td>Los identificadores ESC-01 a ESC-05 se reutilizan con significados distintos en M01, M02, M05, M06, M07 (§17.6: ESC-01 pago duplicado, ESC-04 caída del proveedor), M15, T08, T09 y T11. Además, AC-08 de <code>07</code> cita M07 §17.6 para el caso de hermanos, que está en otros anexos.</td><td>Varios anexos; <code>07</code> AC-08</td><td>Los casos citan siempre &quot;ESC-0x de &lt;anexo&gt; §&lt;sección&gt;&quot;.</td></tr><tr><td>OBS-25-07</td><td>El plan §9.8 describe ESC-SRV-INT-02 y ESC-SRV-INT-03 como escenarios de pagos y §10.2 lista contenidos que no coinciden con T12. Coincide con OBS-05 de <code>07</code>.</td><td><code>03</code> §9.8, §10.2; T12 §1.7</td><td>Se usa el contenido de T12.</td></tr><tr><td>OBS-25-08</td><td>RF-COB-075 dice que si falla la carga de crédito prepago &quot;se revierte&quot;, mientras RF-MED-115, ESC-MED-22 y AC-16 envían la recarga fallida a una bandeja sin emitir un segundo token; RF-MED-113 figura &quot;a validar&quot; (PA-MED-04).</td><td>M07; M03; <code>07</code> AC-16; <code>08</code> GO-25</td><td>Los casos de prepago siguen ESC-MED-22 y GO-25; la definición de RF-MED-113 queda pendiente de PA-MED-04. <strong>Resuelta:</strong> RF-COB-075 ya no dice &quot;se revierte&quot;; la recarga fallida sigue RF-MED-115 y ESC-MED-22.</td></tr><tr><td>OBS-25-09</td><td>ESC-MED-21 da la orden de trabajo por cerrada y ESC-SRV-ELE-07 indica que la orden no cierra (PRM-CAT-041).</td><td>M03; T12 §4.7</td><td>CPA-O7-012 verifica la operación remota pendiente con reintentos (común a ambos) y deja el estado final de la orden de trabajo sujeto a la aclaración de esta observación. <strong>Resuelta (05-11-2026):</strong> ESC-MED-21 distingue PRM-CAT-041 (default <code>true</code>: la OT no cierra), igual que ESC-SRV-ELE-07.</td></tr><tr><td>OBS-25-10</td><td>ESC-MED-37 está en M03 (O7), pero el RF que lo sostiene (RF-MED-129) está asignado a O8.</td><td>M03; <code>03</code></td><td>El escenario se cubre en CPA-O8-008, junto con la compra mayorista de energía. <strong>Sin cambio:</strong> un escenario puede estar en el anexo y ejecutarse en la ola de su RF (O8); no es contradicción.</td></tr><tr><td>OBS-25-11</td><td>El plan §4.8 asigna ESC-UXD-01 a ESC-UXD-25 a O0, aunque el editor de marca y el diccionario que prueban varios de ellos son de O1.</td><td><code>03</code> §4.8; T03</td><td>Los escenarios de marca y diccionario se cubren en O1 (CPA-O1-015).</td></tr><tr><td>OBS-25-12</td><td>ESC-04 de T01 figura en O1, pero requiere pago y CAE, que llegan en O4 y O5.</td><td>T01 §17; <code>03</code></td><td>Se parte en CPA-O1-016 (parte de plataforma) y CPA-O5-006 (completo, AC-15 de <code>07</code>).</td></tr><tr><td>OBS-25-13</td><td>ESC-SUE-30 y RN-SUE-091 rechazan una liquidación propia y otra externa del mismo período, mientras el criterio de salida de O9 pide dos períodos en paralelo con el sistema anterior.</td><td>M16; <code>03</code> O9</td><td>CPA-O9-001 compara los dos períodos contra la importación externa y verifica a la vez el rechazo de ESC-SUE-30; cómo conviven ambos requisitos en el paralelo de sueldos queda a definir.</td></tr><tr><td>OBS-25-14</td><td>Nombre, slug y CUIT de TEN-001 difieren entre anexos (ya registrado como C-16 en el plan §19).</td><td>T01 §18; otros anexos; <code>03</code> §19</td><td>Se usan los datos de T01 §18. <strong>Resuelta (05-11-2026):</strong> M02, T05, T12, T03 y M19 usan R14 del plan (<code>coop-ejemplo-a</code> &quot;Cooperativa Ejemplo A&quot; y <code>coop-ejemplo-b</code> &quot;Cooperativa Ejemplo B&quot;).</td></tr><tr><td>OBS-25-15</td><td>La duración del hipercuidado y los plazos de corrección de defectos posteriores al corte figuran &quot;a definir&quot;.</td><td><code>08</code>; T07</td><td>Los casos de corte no fijan plazos; solo verifican que el procedimiento exista y se registre.</td></tr><tr><td>OBS-25-16</td><td>La escala de prioridad P1 a P3 de la sección 1.2 es una convención de este documento, no un requisito de la especificación.</td><td>—</td><td>Se propone para revisión con QA.</td></tr><tr><td>OBS-25-17</td><td>T07 §9.6 punto 9 remite a §17.6, que no contiene lo referido. Coincide con OBS-04 de <code>07</code>.</td><td>T07</td><td>Se usa el criterio de T07 §17.4. <strong>Resuelta (05-11-2026):</strong> T07 §9.6 punto 9 remite a §17.4.</td></tr><tr><td>OBS-25-18</td><td>Los escenarios PR-POR-15 (formulario de adherentes), PR-POR-26 (espacio de empleado), PR-POR-32 (&quot;ver como socio&quot;), PR-POR-37 (visita sin mapa) y PR-POR-38 (auditoría axe) no tienen ola explícita en M19 ni en el plan.</td><td>M19 §17; <code>03</code></td><td>Se asignan a O10, O9, O2, O2 y O2 para medir la cobertura y quedan sin caso en esta versión.</td></tr></tbody></table>`,43)])])}const h=t(r,[["render",i]]);export{m as __pageData,h as default};
